import math

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
        for x_or_y(7, 34, 12) == 34 (since 7 is prime)
        for x_or_y(15, 8, 5) == 5   (since 15 is not prime)
    """

    # Helper function to check if a number is prime
    def is_prime(num):
        if num <= 1:
            return False
        limit = int(math.sqrt(num)) + 1
        for i in range(2, limit):
            if num % i == 0:
                return False
        return True

    # Main logic based on the problem description
    if is_prime(n):
        return x
    else:
        return y

# --- Testing Examples from your prompt ---
print(x_or_y(7, 34, 12))   # Output: 34 (because 7 is prime)
print(x_or_y(15, 8, 5))    # Output: 5  (because 15 is not prime)

# Additional test cases for verification
print(x_or_y(2, 99, 0))    # Output: 99 (2 is the smallest prime)
print(x_or_y(4, 10, 20))   # Output: 20 (4 is not prime)

